以下是一个简单的基于80c51的嵌入式系统代码，能够实现基本的控制功能：

```c
#include <reg52.h>    // 包含头文件和常量定义

#define LED P1       // LED控制端口
#define BEEP P2.3     // 蜂鸣器控制端口
#define KEY P3.4      // 按键输入端口

sbit LED1 = LED^0;   // 定义LED1
sbit LED2 = LED^1;   // 定义LED2

unsigned int cnt = 0;  // 统计按键次数

// 延时函数，用于避免蜂鸣器出现声音紊乱
void delay(unsigned int ms)  
{
    unsigned int i, j;
    for (i = 0; i < ms; i++)
        for (j = 0; j < 125; j++);
}

void main()
{
    EA  = 1;    // 开启总中断
    ET0 = 1;    // 开启定时器0中断

    TMOD = 0x01;    // 设置定时器0为模式1
    TH0 = 0xFC;     // 设置定时器初始值，默认1ms中断一次
    TL0 = 0x66; 

    TR0 = 1;    // 开启定时器0

    while(1)
    {
        // 每隔一段时间检测一次按键状态
        if(cnt >= 20)
        {
            cnt = 0;

            // 如果按键没有按下，则继续等待
            if(KEY == 1)
            {
                continue;
            }
            else
            {
                // 如果按键按下，则切换LED和蜂鸣器的状态
                LED1 = !LED1;
                BEEP = !BEEP;

                // 延时一段时间避免蜂鸣器出现声音紊乱
                delay(100);

                LED2 = !LED2;   // 切换LED2状态
            }
        }
    }
}

// 定时器0中断处理函数，用于统计按键次数
void timer0() interrupt 1
{
    TH0 = 0xFC;     // 重新设置计时值，实现1ms定时
    TL0 = 0x66;
    cnt++;         // 统计按键次数
}
```

上述代码实现了一个简单的基于80c51的嵌入式系统代码，能够实现基本的控制功能，包括LED和蜂鸣器的控制，以及按键输入的统计。

