#include <curl/curl.h>
#include <stdio.h>

int main(int argc, char* argv[])
{
    CURL* curl;
    CURLcode res;
    FILE* fp;
    char* file = "test.txt";  // 待上传文件名
    const char* remote_path = "/test/";  // 上传到FTP服务器的目录
    const char* url = "ftp://ftp.example.com/";  // FTP服务器地址
    const char* userpwd = "username:password";  // 用户名和密码

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        fp = fopen(file, "rb");
        if (fp) {
            // 设置curl选项
            curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_USERPWD, userpwd);
            curl_easy_setopt(curl, CURLOPT_READDATA, fp);
            curl_easy_setopt(curl, CURLOPT_FTP_CREATE_MISSING_DIRS, 1L);
            curl_easy_setopt(curl, CURLOPT_FTP_CREATE_MISSING_DIRS, 1L);
            curl_easy_setopt(curl, CURLOPT_INFILESIZE_LARGE,  (curl_off_t)-1);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                printf("curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            }
            fclose(fp);
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return 0;
}
```

