#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> c(n);
    for (int i = 0; i < n; i++) {
        cin >> c[i];
    }
    vector<int> dp(n+1);
    dp[0] = 0;
    dp[1] = c[0];
    for (int i = 2; i <= n; i++) {
        int max_dp = 0;
        for (int j = 1; j <= i; j++) {
            max_dp = max(max_dp, dp[j-1] + (i-j+1) * c[i-1]);
        }
        dp[i] = max_dp;
    }
    cout << dp[n] << endl;
    return 0;
} 

Сначала мы считываем входные данные. Вектор c содержит стоимости одного сантиметра волос за каждый день.

Далее мы создаем вектор dp размером n+1, где dp[i] будет содержать максимальную денежную сумму, которую можно заработать на продаже волос за первые i дней. Например, dp[0] = 0 означает, что до первого дня ничего не заработано.

Затем мы заполняем вектор dp динамическим программированием. Для каждого дня i мы берем максимальную сумму заработка из всех возможных вариантов продажи волос за предыдущие дни, т.е. за j-1 дней (где j <= i) и продажей волос за последний день i, умноженной на количество сантиметров волос (i-j+1). Таким образом, мы решаем задачу на каждом шаге, используя уже решенные подзадачи.

Наконец, мы выводим dp[n], которое содержит максимальную денежную сумму, которую можно заработать за все n дней.

