Примерный код:

```javascript
// читаем выбранный стиль из localStorage и устанавливаем его по умолчанию
const selectedStyle = localStorage.getItem('selectedStyle') || 'styles.css';

// создаем новый тег link и устанавливаем атрибуты
const styleLink = document.createElement('link');
styleLink.setAttribute('href', selectedStyle);
styleLink.setAttribute('rel', 'stylesheet');

// добавляем новый тег в разметку
document.head.appendChild(styleLink);

// обработчик изменения стиля
function changeStyle(newStyle) {
  // удаляем старый тег link
  document.head.removeChild(styleLink);

  // создаем новый тег link и устанавливаем атрибуты
  const newLink = document.createElement('link');
  newLink.setAttribute('href', newStyle);
  newLink.setAttribute('rel', 'stylesheet');

  // добавляем новый тег в разметку
  document.head.appendChild(newLink);

  // сохраняем выбранный стиль в localStorage
  localStorage.setItem('selectedStyle', newStyle);
}

