There is an issue with the `reverseArray()` function. It should swap the elements in the array instead of assigning the value of `temp` to `arr[n-i]`. Also, it should only iterate over half the array to avoid swapping elements twice.

The fixed code should look like this:

```
#include<iostream>
using namespace std;

void reverseArray(int arr[], int n) {
    for(int i=0; i<n/2; i++) {
        int temp = arr[i];
        arr[i] = arr[n-i-1];
        arr[n-i-1] = temp;
    }
}

int main() {
    int arr[5];
    for(int i=0; i<5; i++) {
        cin>>arr[i];
    }
    reverseArray(arr, 5);
    for(int i=0; i<5; i++) {
        cout<<arr[i]<<" ";
    }
    return 0;
}
```

