```
% 读取彩色图像
img = imread('color_image.jpg');

% 将图像转换到HSV空间
hsv_img = rgb2hsv(img);

% 分离出各个通道
h_channel = hsv_img(:,:,1);
s_channel = hsv_img(:,:,2);
v_channel = hsv_img(:,:,3);

% 对亮度通道进行直方图均衡化
v_channel_eq = histeq(v_channel);

% 合并各通道
hsv_img_eq = cat(3, h_channel, s_channel, v_channel_eq);

% 将图像转换回RGB空间
rgb_img_eq = hsv2rgb(hsv_img_eq);

% 显示原图和均衡化后的图像
figure;
subplot(1, 2, 1);
imshow(img);
title('原图');

subplot(1, 2, 2);
imshow(rgb_img_eq);
title('均衡化后的图像');
```

